def korean_number(n):
    if n == 0:
        return "영"
    digits = ["", "일", "이", "삼", "사", "오", "육", "칠", "팔", "구"]
    units = ["천", "백", "십", ""]

    def read_group(num):
        parts = []
        for i, unit in enumerate(units):
            d = (num // (10 ** (3 - i))) % 10
            if d == 0:
                continue
            parts.append(unit if d == 1 and unit else digits[d] + unit)
        return "".join(parts)

    upper, lower = divmod(n, 10000)
    result = ""
    if upper:
        result += read_group(upper) + "만"
    if lower:
        result += read_group(lower)
    return result
